import os
from typing import Any, Dict, Optional

import requests


class FederatedLoginError(Exception):
    pass


class FederatedProfileFetcher:
    AUTH0_USERINFO_URL = "https://{domain}/userinfo"

    def __init__(self, domain: Optional[str] = None, timeout: int = 10) -> None:
        self.domain = domain or os.environ.get("AUTH0_DOMAIN")
        if not self.domain:
            raise ValueError("Missing Auth0 domain. Set AUTH0_DOMAIN or pass domain.")
        self.timeout = timeout

    def fetch_and_normalize(self, access_token: str) -> Dict[str, Any]:
        if not access_token:
            raise ValueError("access_token is required")

        raw = self._fetch_userinfo(access_token)
        return self._normalize_claims(raw)

    def _fetch_userinfo(self, access_token: str) -> Dict[str, Any]:
        url = self.AUTH0_USERINFO_URL.format(domain=self.domain)
        resp = requests.get(
            url,
            headers={
                "Authorization": f"Bearer {access_token}",
                "Accept": "application/json",
            },
            timeout=self.timeout,
        )

        if resp.status_code != 200:
            detail = None
            try:
                detail = resp.json()
            except Exception:
                detail = resp.text
            raise FederatedLoginError(f"Auth0 userinfo request failed: {resp.status_code} {detail}")

        data = resp.json()
        if not isinstance(data, dict):
            raise FederatedLoginError("Invalid Auth0 userinfo response")
        return data

    def _normalize_claims(self, claims: Dict[str, Any]) -> Dict[str, Any]:
        sub = self._first_str(claims, "sub")
        if not sub:
            raise FederatedLoginError("Missing required subject claim: sub")

        given_name = self._first_str(claims, "given_name")
        family_name = self._first_str(claims, "family_name")
        name = self._first_str(claims, "name")
        nickname = self._first_str(claims, "nickname")
        preferred_username = self._first_str(claims, "preferred_username")
        email = self._first_str(claims, "email")
        picture = self._first_str(claims, "picture")
        locale = self._first_str(claims, "locale")
        updated_at = self._first_str(claims, "updated_at")

        if not name:
            combined = " ".join(part for part in [given_name, family_name] if part)
            name = combined or nickname or preferred_username or email or sub

        provider, provider_user_id = self._split_subject(sub)

        normalized = {
            "id": sub,
            "subject": sub,
            "provider": provider,
            "provider_user_id": provider_user_id,
            "email": email,
            "email_verified": self._to_bool(claims.get("email_verified")),
            "name": name,
            "given_name": given_name,
            "family_name": family_name,
            "nickname": nickname,
            "preferred_username": preferred_username,
            "picture_url": picture,
            "locale": locale,
            "updated_at": updated_at,
            "raw_claims": claims,
        }

        return normalized

    @staticmethod
    def _split_subject(sub: str) -> Dict[str, str] | tuple[str, str]:
        if "|" in sub:
            provider, provider_user_id = sub.split("|", 1)
            return provider, provider_user_id
        return "unknown", sub

    @staticmethod
    def _first_str(data: Dict[str, Any], key: str) -> Optional[str]:
        value = data.get(key)
        return value if isinstance(value, str) and value.strip() else None

    @staticmethod
    def _to_bool(value: Any) -> Optional[bool]:
        if isinstance(value, bool):
            return value
        if value is None:
            return None
        if isinstance(value, str):
            lowered = value.strip().lower()
            if lowered in {"true", "1", "yes"}:
                return True
            if lowered in {"false", "0", "no"}:
                return False
        if isinstance(value, (int, float)):
            return bool(value)
        return None
